//! Battle data, generated by `tools/battle_data.py` from PokeAPI's data: base stats,
//! the damaging moves and the moves that raise or lower stats, and the moves each Pokémon
//! learns by level.

pub struct Move {
    pub name: &'static str,
    /// Index into `pokemon::TYPES`.
    pub t: u8,
    /// 0 for a status move (it only changes stats).
    pub power: u8,
    /// 0 = never misses.
    pub acc: u8,
    pub special: bool,
    pub prio: i8,
    /// How many times it can be used in a battle.
    pub pp: u8,
    /// Stat stage changes: (Attack, Defense, Sp. Atk, Sp. Def, Speed, accuracy, evasion as
    /// 0..7, how many stages).
    pub stats: &'static [(u8, i8)],
    /// The chance (%) of the stat changes.
    pub chance: u8,
    /// The stat changes are the user's own (Swords Dance, Close Combat), not the target's.
    pub on_user: bool,
}

